#!/usr/bin/env bash
# E13 learning cycle: exact queue commands (printed by `python -m vsa_embed.experiments.e13_cycle plan --config
# experiments/e13-learning-cycle/t5.yaml`, which also writes the trainer configs under configs/t5/).
# NOT EXECUTED by the agent that wrote them. Run from the repository root of the main checkout after merging this branch:
#   cd /home/bhux/workplace/VSA-LLM && PY=/home/bhux/anaconda3/envs/vsa-repro/bin/python
# Each line is `e13_cycle enqueue` = `jobqueue add` with a fractional priority (the `jobqueue add` CLI parses --priority as an
# integer; e9_plan --queue adds fractional levels the same way, through `jobqueue.add`). Jobs get env PYTHONPATH=src.
# Priorities (lower runs first; fractional levels inside one slot, as e9_plan --level-step):
#   54.4985 stage 0: data preparation (CPU work in the GPU lane, ≈ 10 min each), the stage-0 C5 runs, then learn / write
#           (queued after the trainings, so they run after them: equal priorities are first come, first served)
#   54.4986 stage 4 (round 2: read / noread / fvt / gold / defs / random + C0p / C2 references)
#   54.4987 stage 5 (frozen 4-bit host: RTN int4 and NF4; q4-read / q4-noread / qlora / qlora-read)
#   54.4988 evaluations (stage 3: reason)
#   54.4989 report (job name contains "-report": the CPU lane takes it once everything above is done)
# GPU-h from the measured per-step costs of the E9 T5 runs (metrics.jsonl median train tokens/s: SmolLM2-360M 12,767;
# Qwen3-1.7B 4,205) plus evaluation passes. T5 total ≈ 35.2 GPU-h (SmolLM2-360M ≈ 20.5, Qwen3-1.7B ≈ 14.5, preparation 0.3).
# Preconditions: the E9 T5 runs experiments/e9-retrofit/runs/t5/SmolLM2-360M-full-{C0p,C2}-s{1,2,3}/final.pt (the C0p / C2
# references; present on 2026-10-08). Stage-5 runs keep trainable-only states (open them with training.lm.load_final).
set -euo pipefail
: "${PY:?set PY to the pinned interpreter}"

# ---------------------------------------------------------------- T5 (54.4985–54.4989)
PYTHONPATH=src $PY -m vsa_embed.experiments.e13_cycle enqueue --name e13-t5-prep-qwen3 --priority 54.4985 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.e13_cycle prepare --config experiments/e13-learning-cycle/t5.yaml --family qwen3   # ≈ 0.15 GPU-h
